-- Run against the configured project. All test records and setting changes roll back.
begin;
do $$
declare form jsonb;events jsonb;opts jsonb;q jsonb;r jsonb;b uuid;request uuid;token text:=gen_random_uuid()::text;cfg jsonb;failed boolean;
begin
 assert jsonb_array_length(public.booking_package_catalog_list())=18,'Catalog must contain all published packages';
 events:='[{"event_name":"হলুদ","event_date":"2099-11-01","start_time":"16:00","end_time":"20:00","photographers":1,"cinematographers":0,"drone":false,"special_photos":50}]';
 form:=jsonb_build_object('client_name','TEST VALID FORM','phone','00000000000','events',events,'signature_data',repeat('x',50),'signature_name','TEST','consent',true);
 opts:='{"city":"ময়মনসিংহ","travel":{}}';
 q:=public.booking_custom_quote(events,opts);assert (q->>'total')::numeric=5200,'Coverage + editing + travel';
 q:=public.booking_custom_quote(events||events,opts);assert (q->>'travel')::numeric=200,'Same day travel must not duplicate';
 q:=public.booking_custom_quote('[{"event_name":"Wedding","event_date":"2099-11-01","start_time":"22:00","end_date":"2099-11-02","end_time":"02:00","photographers":1,"cinematographers":0}]',opts);assert (q->>'total')::numeric=4400,'Overnight travel';
 failed:=false;begin perform public.booking_custom_quote(events,'{"city":"not allowed"}');exception when others then failed:=true;end;assert failed,'Unapproved city rejected';
 failed:=false;begin perform public.booking_custom_save_config('invalid','{}',1);exception when others then failed:=true;end;assert failed,'Rates require admin';
 assert not has_table_privilege('anon','public.booking_custom_settings','UPDATE'),'No direct settings writes';
 assert not has_table_privilege('anon','public.booking_payment_requests','SELECT'),'No public payment reads';
 insert into public.booking_admin_sessions(token_hash,expires_at) values(encode(extensions.digest(token,'sha256'),'hex'),now()+interval '1 minute');
 cfg:=public.booking_custom_config();cfg:=cfg||'{"payment_accounts":{"BKASH":"TEST_ONLY_NOT_A_REAL_ACCOUNT"}}';
 cfg:=public.booking_custom_save_config(token,cfg,(cfg->>'revision')::integer);
 opts:='{"mode":"fixed","package_id":"regular-basic","allow_publish":true,"terms_advance":true,"terms_half":true,"terms_final":true,"payment_proof":{"amount":2000,"method":"BKASH","transaction_id":"TEST_ROLLBACK_ONLY","payer_phone":"TEST"}}';
 r:=public.submit_package_booking(jsonb_build_object('client_name','TEST ROLLBACK','phone','00000000000','events',events,'signature_data',repeat('x',50),'signature_name','TEST','consent',true,'advance_paid',99999,'discount',99999,'package_amount',1),opts,15000,(cfg->>'revision')::integer);
 b:=(r->>'id')::uuid;assert (r->'payment_plan'->>'initial')::numeric=2000,'Long-term advance';assert (r->'payment_plan'->>'half_total')::numeric=7500,'50% includes initial';
 assert (select package_amount=15000 and advance_paid=0 and discount=0 from public.booking_clients where id=b),'Server overwrites client prices';
 assert (select count(*)=0 from public.booking_payments where booking_id=b),'Pending proof is not paid';
 select id into request from public.booking_payment_requests where booking_id=b;
 perform public.booking_admin_review_payment(token,request,true);
 assert (select sum(amount)=2000 from public.booking_payments where booking_id=b),'Approval records exactly one deposit';
 failed:=false;begin perform public.booking_admin_review_payment(token,request,true);exception when others then failed:=true;end;assert failed,'Cannot approve twice';
 failed:=false;begin perform public.submit_package_booking(form,opts,1,(cfg->>'revision')::integer);exception when others then failed:=true;end;assert failed,'Tampered price rejected';
 failed:=false;begin perform public.submit_package_booking(form,opts||'{"terms_half":false}',15000,(cfg->>'revision')::integer);exception when others then failed:=true;end;assert failed,'Payment terms required';

 opts:=opts||'{"payment_method":"CASH","payment_proof":null}';
 failed:=false;begin perform public.submit_package_booking(jsonb_build_object('client_name','TEST MISSING ADVANCE','phone','00000000000','events',events,'signature_data',repeat('x',50),'signature_name','TEST','consent',true),opts,15000,(cfg->>'revision')::integer);exception when others then failed:=true;end;assert failed,'Confirmed-booking requests require a payment';
 opts:=opts||'{"payment_proof":{"method":"CASH","amount":2000,"transaction_id":"OFFICE-TEST-RECEIPT"}}';
 failed:=false;begin perform public.submit_package_booking(form,opts||'{"payment_proof":{"method":"CASH","amount":2000}}',15000,(cfg->>'revision')::integer);exception when others then failed:=true;end;assert failed,'A cash office receipt is required';
 failed:=false;begin perform public.submit_package_booking(form,opts||'{"payment_proof":{"method":"CASH","amount":1999,"transaction_id":"TOO-SMALL"}}',15000,(cfg->>'revision')::integer);exception when others then failed:=true;end;assert failed,'Deposit below 2000 is rejected';
 r:=public.submit_package_booking(jsonb_build_object('client_name','TEST CASH RECEIPT','phone','00000000000','events',events,'signature_data',repeat('x',50),'signature_name','TEST','consent',true),opts,15000,(cfg->>'revision')::integer);
 b:=(r->>'id')::uuid;
 select id into request from public.booking_payment_requests where booking_id=b and method='CASH';
 assert request is not null,'Cash accepts an office receipt reference';
 assert (select count(*)=0 from public.booking_payments where booking_id=b),'Cash claim awaits verification';
 failed:=false;begin perform public.booking_admin_update_booking(token,b,'confirmed',null);exception when others then failed:=true;end;assert failed,'Cannot confirm before receipt verification';
 perform public.booking_admin_review_payment(token,request,true);
 assert public.booking_admin_update_booking(token,b,'confirmed',null),'Verified long-term deposit allows admin confirmation';
 assert (select sum(amount)=2000 from public.booking_payments where booking_id=b and method='CASH'),'Verified cash records one deposit';
 cfg:=public.booking_custom_save_config(token,cfg||'{"cash_enabled":false}',(cfg->>'revision')::integer);
 failed:=false;begin perform public.submit_package_booking(form,opts,15000,(cfg->>'revision')::integer);exception when others then failed:=true;end;assert failed,'Admin can disable cash';

 r:=public.submit_booking_discussion('{"client_name":"TEST DISCUSSION","phone":"00000000000","notes":"Ask about package","consent":true}');
 b:=(r->>'id')::uuid;
 assert (select count(*)=1 from public.booking_discussions where id=b),'Discussion needs no package, date, signature or payment';
 assert not exists(select 1 from public.booking_clients where id=b),'Discussion is not a booking';
 assert public.booking_admin_update_discussion(token,b,'contacted',true),'Discussion can go to recoverable trash';
 assert public.booking_admin_update_discussion(token,b,null,false),'Discussion can be recovered';
 assert (select deleted_at is null and status='contacted' from public.booking_discussions where id=b),'Recovery preserves status';

 cfg:=public.booking_custom_save_config(token,cfg||'{"cash_enabled":true}',(cfg->>'revision')::integer);
 events:='[{"event_name":"City family photoshoot","event_date":"2099-11-01","start_time":"16:00","end_time":"17:00","photographers":1,"cinematographers":0,"drone":false}]';
 opts:='{"mode":"mini","city":"ময়মনসিংহ","travel":{},"allow_publish":false,"city_deposit_terms":true,"payment_method":"CASH","payment_proof":{"method":"CASH","amount":1000,"transaction_id":"MINI-FULL-RECEIPT"}}';
 q:=public.booking_mini_quote(events->0,opts);assert (q->>'total')::numeric=1200,'One-hour 1000 plus daily travel 200';
 assert (q->>'needs_review')::boolean=false,'One-hour package does not use the four-hour minimum';
 q:=public.booking_mini_quote((events->0)||'{"end_time":"18:00"}',opts);assert (q->>'total')::numeric=2200,'Two hours use hourly pricing';
 q:=public.booking_mini_quote((events->0)||'{"end_time":"18:00","special_photos":20}',opts||'{"city":"ঢাকা"}');assert (q->>'total')::numeric=4900,'Dhaka two hours plus 20 edits plus travel';
 assert (q->>'initial')::numeric=2000,'Dhaka pre-booking is capped at 2000';
 r:=public.submit_package_booking(form||jsonb_build_object('events',jsonb_build_array((events->0)||'{"end_time":"18:00","special_photos":20}')),opts||'{"city":"ঢাকা","payment_proof":{"method":"CASH","amount":2000,"transaction_id":"DHAKA-DEPOSIT"}}',4900,(cfg->>'revision')::integer);
 assert (r->'payment_plan'->>'initial')::numeric=2000 and (r->'payment_plan'->>'total')::numeric=4900,'Dhaka checkout preserves 2900 balance';
 failed:=false;begin perform public.booking_custom_save_config(token,cfg||'{"mini_city_deposits":{"ঢাকা":2001}}',(cfg->>'revision')::integer);exception when others then failed:=true;end;assert failed,'City advance cannot exceed 2000';
 update public.booking_custom_settings set allowed_cities=allowed_cities||array['সিলেট'] where id=true;
 failed:=false;begin perform public.booking_mini_quote(events->0,opts||'{"city":"সিলেট"}');exception when others then failed:=true;end;assert failed,'Other cities require discussion until admin sets a deposit';
 failed:=false;begin perform public.booking_mini_quote(events->0,opts||'{"city":"ঢাকা","travel":{"2099-11-01":200}}');exception when others then failed:=true;end;assert failed,'Dhaka travel minimum is 500';
 q:=public.booking_mini_quote((events->0)||'{"start_time":"23:00","end_date":"2099-11-02","end_time":"01:00"}',opts||'{"city":"ঢাকা"}');assert (q->>'total')::numeric=5000,'Overnight Dhaka uses two daily travel charges';
 failed:=false;begin perform public.booking_mini_quote((events->0)||'{"end_time":"17:30"}',opts);exception when others then failed:=true;end;assert failed,'Whole hours required';
 failed:=false;begin perform public.booking_mini_quote(events->0,opts||'{"city":"not allowed"}');exception when others then failed:=true;end;assert failed,'City mini package is city-restricted';
 form:=form||jsonb_build_object('events',events);
 failed:=false;begin perform public.submit_package_booking(form,opts||'{"payment_proof":{"method":"CASH","amount":999,"transaction_id":"MINI-PARTIAL"}}',1200,(cfg->>'revision')::integer);exception when others then failed:=true;end;assert failed,'Mini requires the city deposit';
 r:=public.submit_package_booking(form,opts,1200,(cfg->>'revision')::integer);b:=(r->>'id')::uuid;
 assert (r->'payment_plan'->>'initial')::numeric=1000,'Mini does not require a separate 2000 deposit';
 assert (r->'payment_plan'->>'city_deposit')::boolean,'Mini uses city deposit schedule';
 assert (r->'payment_plan'->>'half_total')::numeric=1000,'No 50 percent requirement for city shoot';
 assert (r->'payment_plan'->>'half_due_date')::date='2099-11-01'::date,'City balance is due on shoot day';
 assert (select client_extra_charge=0 from public.booking_clients where id=b),'Mini does not add legacy publication fee';
 select id into request from public.booking_payment_requests where booking_id=b;
 failed:=false;begin perform public.booking_admin_update_booking(token,b,'confirmed',null);exception when others then failed:=true;end;assert failed,'Mini needs verified deposit';
 perform public.booking_admin_review_payment(token,request,true);
 assert public.booking_admin_update_booking(token,b,'confirmed',null),'Verified 1000 deposit confirms mini booking';
 cfg:=public.booking_custom_save_config(token,cfg||'{"mini_enabled":false}',(cfg->>'revision')::integer);
 failed:=false;begin perform public.booking_mini_quote(events->0,opts);exception when others then failed:=true;end;assert failed,'Admin can disable city mini package';
end $$;
rollback;
